//! Comparison of the Rust engine with the golden tables generated by the Python reference
//! (`rust/golden/generate_stage*_golden.py`). Used by the integration tests and by
//! `amcrax verify <target>`, which writes the machine-readable comparison report.
//!
//! Deviation measures (each check states its rule and gate):
//!
//! * `rel`: `|rust - python| / |python|` (`|rust - python|` when python is 0), or, where the
//!   quantity is a sum of terms that can cancel, `|rust - python| / max(|python|, scale)` with the
//!   stated term scale (the condition of the sum); identical values (including two NaN or two equal
//!   infinities) have deviation 0, a NaN or infinity on one side only has deviation infinity;
//! * `abs`: `|rust - python|`;
//! * `exact`: 0 when the decision (error class, root count, bracket, flag) is identical, else 1;
//! * `info`: reported, not gated.

pub mod stage1;
pub mod stage2;
pub mod stage3;
pub mod stage4;

use crate::error::EngineError;
use crate::provenance::sha256_hex;
use crate::species::Species;
use serde::Serialize;
use serde_json::Value;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

/// Comparison rule of a check.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum Rule {
    Rel,
    Abs,
    Exact,
    Info,
}

/// One gated quantity of the report.
#[derive(Debug, Clone, PartialEq, Serialize)]
pub struct Check {
    pub id: String,
    pub quantity: String,
    pub rule: Rule,
    pub gate: f64,
    pub n_cases: usize,
    pub n_fail: usize,
    #[serde(serialize_with = "ser_f64")]
    pub max_deviation: f64,
    pub worst_case: String,
    pub passed: bool,
    pub note: String,
}

fn ser_f64<S: serde::Serializer>(v: &f64, s: S) -> Result<S::Ok, S::Error> {
    if v.is_finite() {
        s.serialize_f64(*v)
    } else if v.is_nan() {
        s.serialize_str("nan")
    } else if *v > 0.0 {
        s.serialize_str("inf")
    } else {
        s.serialize_str("-inf")
    }
}

/// A list of checks with failure details.
#[derive(Debug, Clone, PartialEq, Serialize, Default)]
pub struct Report {
    pub target: String,
    pub checks: Vec<Check>,
    /// Details of the first failing cases of every failing check.
    pub failures: Vec<String>,
    /// Findings that are reported, not gated (stiffness, documented differences).
    pub findings: Vec<String>,
}

impl Report {
    /// A new, empty report.
    pub fn new(target: &str) -> Report {
        Report {
            target: target.to_string(),
            ..Report::default()
        }
    }

    /// True when every check passed.
    pub fn passed(&self) -> bool {
        self.checks.iter().all(|c| c.passed)
    }

    /// Add the result of an accumulator.
    pub fn push(&mut self, acc: Acc) {
        let (c, f) = acc.finish();
        self.failures.extend(f);
        self.checks.push(c);
    }

    /// Append another report.
    pub fn extend(&mut self, other: Report) {
        self.checks.extend(other.checks);
        self.failures.extend(other.failures);
        self.findings.extend(other.findings);
    }

    /// Human-readable table.
    pub fn render(&self) -> String {
        let mut s = format!("verify {}\n", self.target);
        for c in &self.checks {
            s.push_str(&format!(
                "  {:<4} {:<44} n={:<6} max={:<11.3e} gate={:<8.1e} {:?} {}\n",
                if c.passed { "ok" } else { "FAIL" },
                c.id,
                c.n_cases,
                c.max_deviation,
                c.gate,
                c.rule,
                if c.n_fail > 0 {
                    format!("({} failing, worst {})", c.n_fail, c.worst_case)
                } else {
                    String::new()
                }
            ));
        }
        for f in &self.findings {
            s.push_str(&format!("  finding: {f}\n"));
        }
        for f in self.failures.iter().take(60) {
            s.push_str(&format!("  failure: {f}\n"));
        }
        s.push_str(&format!(
            "{}: {} checks, {} failed\n",
            if self.passed() { "PASSED" } else { "FAILED" },
            self.checks.len(),
            self.checks.iter().filter(|c| !c.passed).count()
        ));
        s
    }
}

/// Accumulates the deviations of one quantity.
#[derive(Debug, Clone)]
pub struct Acc {
    id: String,
    quantity: String,
    rule: Rule,
    gate: f64,
    n: usize,
    n_fail: usize,
    max_dev: f64,
    worst: String,
    fails: Vec<String>,
    note: String,
}

/// Deviation of `r` from `p` under `rule` (`scale` > 0 replaces a smaller `|p|` for `Rel`).
pub fn deviation(rule: Rule, r: f64, p: f64, scale: f64) -> f64 {
    if r == p || (r.is_nan() && p.is_nan()) {
        return 0.0;
    }
    if !r.is_finite() || !p.is_finite() {
        return f64::INFINITY;
    }
    let d = (r - p).abs();
    match rule {
        Rel | Info => {
            let den = p.abs().max(scale);
            if den > 0.0 { d / den } else { d }
        }
        Abs => d,
        Exact => {
            if d == 0.0 {
                0.0
            } else {
                1.0
            }
        }
    }
}
use Rule::{Abs, Exact, Info, Rel};

impl Acc {
    fn new(id: &str, quantity: &str, rule: Rule, gate: f64) -> Acc {
        Acc {
            id: id.to_string(),
            quantity: quantity.to_string(),
            rule,
            gate,
            n: 0,
            n_fail: 0,
            max_dev: 0.0,
            worst: String::new(),
            fails: Vec::new(),
            note: String::new(),
        }
    }
    /// Relative deviation gate.
    pub fn rel(id: &str, quantity: &str, gate: f64) -> Acc {
        Acc::new(id, quantity, Rel, gate)
    }
    /// Absolute deviation gate.
    pub fn abs(id: &str, quantity: &str, gate: f64) -> Acc {
        Acc::new(id, quantity, Abs, gate)
    }
    /// Identical decisions.
    pub fn exact(id: &str, quantity: &str) -> Acc {
        Acc::new(id, quantity, Exact, 0.0)
    }
    /// Reported only (relative deviation).
    pub fn info(id: &str, quantity: &str) -> Acc {
        Acc::new(id, quantity, Info, f64::INFINITY)
    }
    /// Attach a note.
    pub fn note(mut self, s: &str) -> Acc {
        self.note = s.to_string();
        self
    }

    fn record(&mut self, case: &str, dev: f64, detail: impl FnOnce() -> String) {
        self.n += 1;
        if dev > self.max_dev || (self.n == 1 && dev.is_nan()) {
            self.max_dev = dev;
            self.worst = case.to_string();
        }
        let fail = self.rule != Info && (dev.is_nan() || dev > self.gate);
        if fail {
            self.n_fail += 1;
            if self.fails.len() < 6 {
                self.fails
                    .push(format!("{}: {case}: {}", self.id, detail()));
            }
        }
    }

    /// Compare a value.
    pub fn add(&mut self, case: &str, rust: f64, python: f64) {
        self.add_scaled(case, rust, python, 0.0);
    }

    /// Compare a value with a term scale (see the module documentation).
    pub fn add_scaled(&mut self, case: &str, rust: f64, python: f64, scale: f64) {
        let dev = deviation(self.rule, rust, python, scale);
        self.record(case, dev, || {
            format!("rust {rust:e} python {python:e} deviation {dev:e}")
        });
    }

    /// Record a decision (`ok` = identical).
    pub fn add_bool(&mut self, case: &str, ok: bool, detail: impl FnOnce() -> String) {
        self.record(case, if ok { 0.0 } else { 1.0 }, detail);
    }

    /// Number of cases so far.
    pub fn len(&self) -> usize {
        self.n
    }

    /// True when no case was added.
    pub fn is_empty(&self) -> bool {
        self.n == 0
    }

    fn finish(self) -> (Check, Vec<String>) {
        let passed = self.n_fail == 0;
        (
            Check {
                id: self.id,
                quantity: self.quantity,
                rule: self.rule,
                gate: self.gate,
                n_cases: self.n,
                n_fail: self.n_fail,
                max_deviation: self.max_dev,
                worst_case: self.worst,
                passed,
                note: self.note,
            },
            self.fails,
        )
    }
}

/// Golden-table directory with its MANIFEST.json.
pub struct Golden {
    dir: PathBuf,
    manifest: Value,
}

impl Golden {
    /// Open `dir` and read its manifest.
    pub fn open(dir: &Path) -> Result<Golden, EngineError> {
        let p = dir.join("MANIFEST.json");
        let text = std::fs::read(&p)
            .map_err(|e| EngineError::data(p.display().to_string(), e.to_string()))?;
        let manifest: Value = serde_json::from_slice(&text)
            .map_err(|e| EngineError::data(p.display().to_string(), e.to_string()))?;
        Ok(Golden {
            dir: dir.to_path_buf(),
            manifest,
        })
    }

    /// Generator metadata of the manifest.
    pub fn meta(&self) -> Value {
        self.manifest.get("meta").cloned().unwrap_or(Value::Null)
    }

    /// Read `rel` (a path listed in the manifest), check its SHA-256 and parse it.
    pub fn load(&self, rel: &str) -> Result<Value, EngineError> {
        let want = self.manifest["files"][rel]["sha256"]
            .as_str()
            .ok_or_else(|| EngineError::data(rel, "not listed in MANIFEST.json"))?;
        let path = rel.split('/').fold(self.dir.clone(), |p, s| p.join(s));
        let bytes = std::fs::read(&path).map_err(|e| EngineError::data(rel, e.to_string()))?;
        let got = sha256_hex(&bytes);
        if got != want {
            return Err(EngineError::data(
                rel,
                format!("SHA-256 {got} does not match MANIFEST.json ({want})"),
            ));
        }
        serde_json::from_slice(&bytes).map_err(|e| EngineError::data(rel, e.to_string()))
    }
}

/// A golden float (`"nan"`, `"inf"`, `"-inf"` strings for non-finite values; NaN for anything else).
pub fn num(v: &Value) -> f64 {
    match v {
        Value::Number(n) => n.as_f64().unwrap_or(f64::NAN),
        Value::String(s) => match s.as_str() {
            "inf" => f64::INFINITY,
            "-inf" => f64::NEG_INFINITY,
            _ => f64::NAN,
        },
        _ => f64::NAN,
    }
}

/// The Python exception class name when `v` records one.
pub fn py_error(v: &Value) -> Option<&str> {
    v.get("error").and_then(Value::as_str)
}

/// Whether a Rust error corresponds to the Python exception class.
pub fn error_matches(py: &str, e: &EngineError) -> bool {
    match py {
        "ValueError" | "KeyError" | "TypeError" | "ZeroDivisionError" => {
            matches!(e, EngineError::Domain(_))
        }
        "RuntimeError" => matches!(e, EngineError::Numerical(_) | EngineError::Bracket(_)),
        _ => false,
    }
}

/// `{"NH3": 0.5, ...}` as `(Species, value)` in the order of the JSON object (sorted keys).
pub fn species_map(v: &Value) -> Result<Vec<(Species, f64)>, EngineError> {
    let obj = v
        .as_object()
        .ok_or_else(|| EngineError::data("golden", "species map expected"))?;
    let mut out = Vec::with_capacity(obj.len());
    for (k, val) in obj {
        let s = Species::from_name(k)
            .ok_or_else(|| EngineError::data("golden", format!("unknown species {k}")))?;
        out.push((s, num(val)));
    }
    out.sort_by_key(|x| x.0.index());
    Ok(out)
}

/// The value of species `s` in a list (NaN when absent).
pub fn lookup(v: &[(Species, f64)], s: Species) -> f64 {
    v.iter().find(|x| x.0 == s).map(|x| x.1).unwrap_or(f64::NAN)
}

/// Compare per-species values: same species set, values under `acc`.
pub fn add_species(
    acc: &mut Acc,
    keys: &mut Acc,
    case: &str,
    rust: &[(Species, f64)],
    python: &Value,
) {
    let Ok(p) = species_map(python) else {
        keys.add_bool(case, false, || "python value is not a species map".into());
        return;
    };
    let same = p.len() == rust.len() && p.iter().all(|(s, _)| rust.iter().any(|r| r.0 == *s));
    keys.add_bool(case, same, || {
        format!(
            "species sets differ: rust {:?} python {:?}",
            rust.iter().map(|x| x.0.name()).collect::<Vec<_>>(),
            p.iter().map(|x| x.0.name()).collect::<Vec<_>>()
        )
    });
    for (s, pv) in &p {
        acc.add(&format!("{case}/{}", s.name()), lookup(rust, *s), *pv);
    }
}

/// Repository root that contains `rust/` (from `AMCRAX_ROOT`, else the current directory or
/// its parent).
pub fn default_repo_root() -> PathBuf {
    if let Some(r) = std::env::var_os(crate::data::ROOT_ENV) {
        let p = PathBuf::from(r);
        if p.join("rust").is_dir() {
            return p;
        }
    }
    for cand in [PathBuf::from("."), PathBuf::from("..")] {
        if cand.join("rust").join("golden").is_dir() {
            return cand;
        }
    }
    PathBuf::from(".")
}

/// Serialise a report with run metadata as JSON text.
pub fn report_json(reports: &[Report], meta: BTreeMap<String, Value>) -> String {
    let checks: Vec<&Check> = reports.iter().flat_map(|r| r.checks.iter()).collect();
    let all = reports.iter().all(Report::passed);
    let v = serde_json::json!({
        "schema": "amcrax.verification/1",
        "description": "Python (reference) versus Rust (port) numerical comparison: for each quantity the \
                        number of cases, the maximum deviation, the gate and pass or fail",
        "meta": meta,
        "all_passed": all,
        "n_checks": checks.len(),
        "reports": reports,
    });
    serde_json::to_string_pretty(&v).unwrap_or_default()
}
